"use strict";

// The pure-JS fallback, declared as a FUNCTION DECLARATION rather than a
// `let`/`var` initializer. That difference is the whole point of RWF-013b:
// JavaScript reassigns a function declaration's binding exactly as freely
// as a variable's, so the declaration form says nothing about whether the
// name still holds this function later in the file.
//
// It carries the exported name directly -- no `inferAssignedName` needed,
// the declaration simply IS named `parse` -- so it is an even easier
// target for a name-based export search than RWF-013's anonymous
// initializer was.
function parse(input) {
  return "safe:" + String(input);
}

// The real implementation replaces the fallback at load time,
// UNCONDITIONALLY. From this line on, `parse` is lib/parse.js's function
// and the declaration above is unreachable dead weight.
parse = require("./lib/parse");

// The package's documented entry point, and the export the rule names.
// At runtime it holds lib/parse.js's function.
exports.parse = parse;

// The same function object under a second name, for callers that want to
// be explicit. Statically resolvable (RWF-004a), unlike `parse` above.
exports.parseSync = require("./lib/parse");
